  F1B0: c3                       clr C
  F1B1: 95 31                    subb A,0x31               ; limit - volume
  F1B3: 50 03                    jnc sv_hp                      ; volume <= limit: keep it
  F1B5: 75 31 19                 mov 0x31,#0x19
